import{z as i,x as p,o as t,c as B,q as A,j as o,D as E,d as r,s,S as n,b as e}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"提示格式敏感","description":"","frontmatter":{"title":"提示格式敏感","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/prompt-format-sensitivity.md","filePath":"llm/prompt-format-sensitivity.md","lastUpdated":1791063341000}'),d={name:"llm/prompt-format-sensitivity.md"};function m(h,a,f,D,c,u){const l=p("Mermaid");return t(),B("div",null,[a[2]||(a[2]=A('<h1 id="提示格式敏感" tabindex="-1">提示格式敏感 <a class="header-anchor" href="#提示格式敏感" aria-label="Permalink to &quot;提示格式敏感&quot;">​</a></h1><div class="epigraph"><p>把冒号换成换行、把选项从 A. 换成 (A)，准确率可以跳几个点。那是格式方差，不是能力跃迁。</p><footer>—— Sclar 等对提示表面特征的量化；HELM 亦长期报告模板敏感</footer></div><p><a href="/llm/loglik-vs-generative-eval">上一课</a>把似然与生成拆开。两套协议都还剩一个自由度：提示的表面句法。本课写格式敏感。缺口不是再讲 few-shot，而是：<strong>同一套题、同一个模型，模板微扰不该被写成新 SOTA。</strong> 后课答案抽取默认格式已经是误差源之一。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Sclar 等人系统扰动分隔符、空格、选项标记、大小写，发现许多模型的准确率分布很宽：均值好看，换一种同样「合理」的模板就跌出置信区间。排行榜若只报作者最顺手的那一条提示，等于在优化提示工程，不是在测模型。</p><p>聊天模板把问题再放大一层：Hugging Face <code>apply_chat_template</code>、系统提示、是否把 few-shot 封进多轮，都会改 token 序列。基座没有聊天模板，Instruct 权重有；把两者放进同一列却用不同封装，格式方差被算进「对齐收益」。</p><p><span class="marginnote">常见误区：看到分数涨了几个点就断定「微调有效」或「新模型更强」。先把模板、系统提示、few-shot 封装逐项对齐再比——很多「提升」在换成同一封装后消失，剩下的才是能力差。</span></p><p><span class="marginnote">格式敏感与<a href="/llm/eval-contamination">污染</a>正交。污染是题见过；格式敏感是题没变、包装变了。两者都会让涨分无法解释，但补丁不同。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>最小协议：冻结一簇模板（不少于数种分隔与选项标记），报告均值与极差，而不是最好的一个。官方脚本（后课 harness）应把模板当版本号的一部分。对 Instruct 模型，额外锁死系统提示是否为空、few-shot 是用户轮还是拼进单轮。</p><p><span class="marginnote">数字实例：若某模型在模板簇上的准确率是 71%、68%、66%、58%，只报最高的 71% 就是广告；报「均值 65.8 ± 极差 13」才能与下一个模型公平对话。极差下降哪怕均值持平，也说明模型对格式更鲁棒，这本身是进步。</span></p><p>比较两个模型时，用<strong>同一簇</strong>模板，禁止各自调到最佳。声称鲁棒，应看极差是否下降，而不是看某一条高峰。</p>',12)),(t(),o(n,null,{default:E(()=>[s(l,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20ITEM%5B%22%E5%90%8C%E4%B8%80%E9%A2%98%22%5D%20--%3E%20T1%5B%22%E6%A8%A1%E6%9D%BF%E7%B0%87%22%5D%0A%20%20T1%20--%3E%20ACC%5B%22%E5%87%86%E7%A1%AE%E7%8E%87%E5%88%86%E5%B8%83%22%5D%0A%20%20ACC%20--%3E%20MEAN%5B%22%E5%9D%87%E5%80%BC%22%5D%0A%20%20ACC%20--%3E%20RNG%5B%22%E6%9E%81%E5%B7%AE%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[r("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,"表面格式改变的是相对位置与特殊符号先验。模型在预训练里见过更多「A.」而不是「(A)」，似然协议会把质量分给更像语料的选项标记，即使内容等价。生成协议则把「先复述再给字母」的路径概率改掉，抽取器随之成功或失败。few-shot 例题的格式若与试题不一致，模型会模仿例题的错格式，试题被判错——这是协议 bug，不是学科无知。",-1)),a[5]||(a[5]=e("p",null,"一次格式扰动如何变成一道「错题」：",-1)),(t(),o(n,null,{default:E(()=>[s(l,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20F%5B%22%E6%8D%A2%E4%B8%80%E4%B8%AA%E5%90%8C%E6%A0%B7%E5%90%88%E7%90%86%E7%9A%84%E6%A8%A1%E6%9D%BF%22%5D%20--%3E%20T%5B%22token%20%E5%BA%8F%E5%88%97%E6%94%B9%E5%8F%98%22%5D%0A%20%20T%20--%3E%20P%5B%22%E7%89%B9%E6%AE%8A%E7%AC%A6%E5%8F%B7%E5%85%88%E9%AA%8C%E8%A2%AB%E8%A7%A6%E5%8F%91%22%5D%0A%20%20P%20--%3E%20G%5B%22%E7%94%9F%E6%88%90%E8%B7%AF%E5%BE%84%E6%94%B9%E5%8F%98%2C%20%E5%A6%82%E5%85%88%E5%A4%8D%E8%BF%B0%E9%A2%98%E7%9B%AE%E5%86%8D%E4%BD%9C%E7%AD%94%22%5D%0A%20%20G%20--%3E%20X%7B%22%E6%8A%BD%E5%8F%96%E5%99%A8%E6%8C%89%E7%BA%A6%E5%AE%9A%E6%A0%BC%E5%BC%8F%E6%8A%A0%E6%9C%80%E7%BB%88%E7%AD%94%E6%A1%88%22%7D%0A%20%20X%20--%3E%7C%22%E5%AF%B9%E4%B8%8D%E4%B8%8A%E7%BA%A6%E5%AE%9A%22%7C%20MISS%5B%22%E5%88%A4%E9%94%99%2C%20%E5%B0%BD%E7%AE%A1%E7%9F%A5%E8%AF%86%E6%AD%A3%E7%A1%AE%22%5D%0A%20%20X%20--%3E%7C%22%E5%AF%B9%E4%B8%8A%22%7C%20OK%5B%22%E6%AD%A3%E5%B8%B8%E8%AE%A1%E5%88%86%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=A('<p><span class="marginnote">「模板簇」可以类比考卷印刷：同一份题用宋体、黑体、楷体各印一版，考生分数本不该变；若一版 90 分一版 70 分，说明这个考生在认字而不是在做题。Sclar 等测得的极差最大能到几十个准确率点——「合理」模板之间的差别就是这么大。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不可能穷尽所有同义改写。目标是把「常见排版」的方差暴露出来，而不是证明对任意扰动不变。下一课答案抽取会处理生成协议里比格式更下游的那一层：从段落里把「最终答案」抠出来。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>模板微扰可造成数点准确率差；只报最佳提示无效。</li><li>报告均值与极差；跨模型必须共用模板簇。</li><li>聊天封装属于格式，不是可忽略的样板。</li><li>出处：Sclar 等对提示表面特征敏感度的量化；HELM 的模板报告传统。</li></ul>',5))])}const T=i(d,[["render",m]]);export{_ as __pageData,T as default};
